-- ============================================================================
-- CREATE TABLES - Normalized data only (no calculated fields)
-- ============================================================================

-- ----------------------------------------------------------------------------
-- Users: People who wind timers.
-- ----------------------------------------------------------------------------
CREATE TABLE users (
  user_id                             TEXT                 PRIMARY KEY,         -- Primary key.
  display_name                        TEXT                                      -- Human name.
);
COMMENT ON TABLE users IS 'People who wind timers.';
COMMENT ON COLUMN users.user_id IS 'Primary key.';
COMMENT ON COLUMN users.display_name IS 'Human name.';

-- ----------------------------------------------------------------------------
-- Timers: Top-level timer assembly. Holds the raw mechanical parameters and the headline runtime DAG: stored torque, remaining minutes, wind state, and whether the bell has rung.
-- ----------------------------------------------------------------------------
CREATE TABLE timers (
  timer_id                            TEXT                 PRIMARY KEY,         -- Primary key.
  label                               TEXT                ,                     -- User-facing label.
  wind_angle_degrees                  NUMERIC             ,                     -- Current angular position of the winding knob, 0..MaxWindDegrees.
  max_wind_degrees                    NUMERIC             ,                     -- Full-wind knob travel; 360 deg = 60 min on a standard dial.
  max_spring_torque_nm                NUMERIC             ,                     -- Mainspring torque at full wind, newton-meters.
  escapement_base_hz                  NUMERIC                                   -- Pallet oscillation frequency in §4.
);
COMMENT ON TABLE timers IS 'Top-level timer assembly. Holds the raw mechanical parameters and the headline runtime DAG: stored torque, remaining minutes, wind state, and whether the bell has rung.';
COMMENT ON COLUMN timers.timer_id IS 'Primary key.';
COMMENT ON COLUMN timers.label IS 'User-facing label.';
COMMENT ON COLUMN timers.wind_angle_degrees IS 'Current angular position of the winding knob, 0..MaxWindDegrees.';
COMMENT ON COLUMN timers.max_wind_degrees IS 'Full-wind knob travel; 360 deg = 60 min on a standard dial.';
COMMENT ON COLUMN timers.max_spring_torque_nm IS 'Mainspring torque at full wind, newton-meters.';
COMMENT ON COLUMN timers.escapement_base_hz IS 'Pallet oscillation frequency in §4.';

-- ----------------------------------------------------------------------------
-- Cases: The outer housing of a timer. The bell is mounted on top of the case.
-- ----------------------------------------------------------------------------
CREATE TABLE cases (
  case_id                             TEXT                 PRIMARY KEY,         -- Primary key.
  houses_timer                        TEXT                ,                     -- Parent timer.
  material                            TEXT                                      -- Case material.
);
COMMENT ON TABLE cases IS 'The outer housing of a timer. The bell is mounted on top of the case.';
COMMENT ON COLUMN cases.case_id IS 'Primary key.';
COMMENT ON COLUMN cases.houses_timer IS 'Parent timer.';
COMMENT ON COLUMN cases.material IS 'Case material.';

-- ----------------------------------------------------------------------------
-- Bells: The bell mounted on top of the case. Struck by the hammer striker when §5 fires.
-- ----------------------------------------------------------------------------
CREATE TABLE bells (
  bell_id                             TEXT                 PRIMARY KEY,         -- Primary key.
  mounted_on_case                     TEXT                ,                     -- Case the bell sits on.
  diameter_mm                         NUMERIC             ,                     -- Bell diameter, mm.
  tone_hz                             NUMERIC                                   -- Dominant tone, Hz.
);
COMMENT ON TABLE bells IS 'The bell mounted on top of the case. Struck by the hammer striker when §5 fires.';
COMMENT ON COLUMN bells.bell_id IS 'Primary key.';
COMMENT ON COLUMN bells.mounted_on_case IS 'Case the bell sits on.';
COMMENT ON COLUMN bells.diameter_mm IS 'Bell diameter, mm.';
COMMENT ON COLUMN bells.tone_hz IS 'Dominant tone, Hz.';

-- ----------------------------------------------------------------------------
-- WindingKnobs: §1 — the dial on the front. Shaft is fixed to the mainspring arbor. Rim carries a printed scale 0..60 read against a fixed pointer on the case.
-- ----------------------------------------------------------------------------
CREATE TABLE winding_knobs (
  winding_knob_id                     TEXT                 PRIMARY KEY,         -- Primary key.
  fixed_to_timer                      TEXT                ,                     -- Parent timer.
  scale_min                           INTEGER             ,                     -- Lower bound of the printed scale.
  scale_max                           INTEGER             ,                     -- Upper bound of the printed scale.
  wind_direction                      TEXT                ,                     -- Clockwise or counter-clockwise.
  shaft_diameter_mm                   NUMERIC             ,                     -- Diameter of the knob shaft.
  pointer_fixed                       BOOLEAN                                   -- True if the case pointer is fixed (it always is on this design).
);
COMMENT ON TABLE winding_knobs IS '§1 — the dial on the front. Shaft is fixed to the mainspring arbor. Rim carries a printed scale 0..60 read against a fixed pointer on the case.';
COMMENT ON COLUMN winding_knobs.winding_knob_id IS 'Primary key.';
COMMENT ON COLUMN winding_knobs.fixed_to_timer IS 'Parent timer.';
COMMENT ON COLUMN winding_knobs.scale_min IS 'Lower bound of the printed scale.';
COMMENT ON COLUMN winding_knobs.scale_max IS 'Upper bound of the printed scale.';
COMMENT ON COLUMN winding_knobs.wind_direction IS 'Clockwise or counter-clockwise.';
COMMENT ON COLUMN winding_knobs.shaft_diameter_mm IS 'Diameter of the knob shaft.';
COMMENT ON COLUMN winding_knobs.pointer_fixed IS 'True if the case pointer is fixed (it always is on this design).';

-- ----------------------------------------------------------------------------
-- Arbors: The shaft driven by the mainspring. Connects §1 (knob shaft) to §2 (mainspring), and carries the §5 cam.
-- ----------------------------------------------------------------------------
CREATE TABLE arbors (
  arbor_id                            TEXT                 PRIMARY KEY,         -- Primary key.
  in_timer                            TEXT                ,                     -- Parent timer.
  diameter_mm                         NUMERIC                                   -- Arbor diameter.
);
COMMENT ON TABLE arbors IS 'The shaft driven by the mainspring. Connects §1 (knob shaft) to §2 (mainspring), and carries the §5 cam.';
COMMENT ON COLUMN arbors.arbor_id IS 'Primary key.';
COMMENT ON COLUMN arbors.in_timer IS 'Parent timer.';
COMMENT ON COLUMN arbors.diameter_mm IS 'Arbor diameter.';

-- ----------------------------------------------------------------------------
-- Mainsprings: §2 — flat coiled steel spring in a drum. Inner end anchors to the arbor; outer end anchors to the case.
-- ----------------------------------------------------------------------------
CREATE TABLE mainsprings (
  mainspring_id                       TEXT                 PRIMARY KEY,         -- Primary key.
  wrapped_on_arbor                    TEXT                ,                     -- Arbor this mainspring drives.
  drum_diameter_mm                    NUMERIC             ,                     -- Diameter of the spring drum.
  material                            TEXT                ,                     -- Spring material.
  inner_end_anchor                    TEXT                ,                     -- Where the inner end anchors (always Arbor).
  outer_end_anchor                    TEXT                                      -- Where the outer end anchors (always Case).
);
COMMENT ON TABLE mainsprings IS '§2 — flat coiled steel spring in a drum. Inner end anchors to the arbor; outer end anchors to the case.';
COMMENT ON COLUMN mainsprings.mainspring_id IS 'Primary key.';
COMMENT ON COLUMN mainsprings.wrapped_on_arbor IS 'Arbor this mainspring drives.';
COMMENT ON COLUMN mainsprings.drum_diameter_mm IS 'Diameter of the spring drum.';
COMMENT ON COLUMN mainsprings.material IS 'Spring material.';
COMMENT ON COLUMN mainsprings.inner_end_anchor IS 'Where the inner end anchors (always Arbor).';
COMMENT ON COLUMN mainsprings.outer_end_anchor IS 'Where the outer end anchors (always Case).';

-- ----------------------------------------------------------------------------
-- GearTrains: §3 — the three-gear stack between mainspring arbor and escapement. Carries the output shaft that drives the dial pointer.
-- ----------------------------------------------------------------------------
CREATE TABLE gear_trains (
  gear_train_id                       TEXT                 PRIMARY KEY,         -- Primary key.
  in_timer                            TEXT                ,                     -- Parent timer.
  reduction_ratio                     NUMERIC                                   -- Total speed-up from arbor to escapement.
);
COMMENT ON TABLE gear_trains IS '§3 — the three-gear stack between mainspring arbor and escapement. Carries the output shaft that drives the dial pointer.';
COMMENT ON COLUMN gear_trains.gear_train_id IS 'Primary key.';
COMMENT ON COLUMN gear_trains.in_timer IS 'Parent timer.';
COMMENT ON COLUMN gear_trains.reduction_ratio IS 'Total speed-up from arbor to escapement.';

-- ----------------------------------------------------------------------------
-- Gears: Individual gears in a gear train. Each has a tooth count and a position in the chain (1, 2, or 3).
-- ----------------------------------------------------------------------------
CREATE TABLE gears (
  gear_id                             TEXT                 PRIMARY KEY,         -- Primary key.
  in_gear_train                       TEXT                ,                     -- Parent gear train.
  position_in_chain                   INTEGER             ,                     -- 1, 2, or 3 — arbor side to escapement side.
  tooth_count                         INTEGER                                   -- Number of teeth on this gear.
);
COMMENT ON TABLE gears IS 'Individual gears in a gear train. Each has a tooth count and a position in the chain (1, 2, or 3).';
COMMENT ON COLUMN gears.gear_id IS 'Primary key.';
COMMENT ON COLUMN gears.in_gear_train IS 'Parent gear train.';
COMMENT ON COLUMN gears.position_in_chain IS '1, 2, or 3 — arbor side to escapement side.';
COMMENT ON COLUMN gears.tooth_count IS 'Number of teeth on this gear.';

-- ----------------------------------------------------------------------------
-- OutputShafts: The shaft at the end of the gear train. Carries the dial pointer.
-- ----------------------------------------------------------------------------
CREATE TABLE output_shafts (
  output_shaft_id                     TEXT                 PRIMARY KEY,         -- Primary key.
  in_gear_train                       TEXT                                      -- Parent gear train.
);
COMMENT ON TABLE output_shafts IS 'The shaft at the end of the gear train. Carries the dial pointer.';
COMMENT ON COLUMN output_shafts.output_shaft_id IS 'Primary key.';
COMMENT ON COLUMN output_shafts.in_gear_train IS 'Parent gear train.';

-- ----------------------------------------------------------------------------
-- DialPointers: Pointer mounted on the output shaft. Reads against the printed scale on the knob rim.
-- ----------------------------------------------------------------------------
CREATE TABLE dial_pointers (
  dial_pointer_id                     TEXT                 PRIMARY KEY,         -- Primary key.
  on_output_shaft                     TEXT                ,                     -- Shaft this pointer is mounted on.
  length_mm                           NUMERIC                                   -- Pointer length.
);
COMMENT ON TABLE dial_pointers IS 'Pointer mounted on the output shaft. Reads against the printed scale on the knob rim.';
COMMENT ON COLUMN dial_pointers.dial_pointer_id IS 'Primary key.';
COMMENT ON COLUMN dial_pointers.on_output_shaft IS 'Shaft this pointer is mounted on.';
COMMENT ON COLUMN dial_pointers.length_mm IS 'Pointer length.';

-- ----------------------------------------------------------------------------
-- Escapements: §4 — escapement assembly: toothed wheel plus two-pronged pallet plus hairspring. Defines the time base.
-- ----------------------------------------------------------------------------
CREATE TABLE escapements (
  escapement_id                       TEXT                 PRIMARY KEY,         -- Primary key.
  in_timer                            TEXT                                      -- Parent timer.
);
COMMENT ON TABLE escapements IS '§4 — escapement assembly: toothed wheel plus two-pronged pallet plus hairspring. Defines the time base.';
COMMENT ON COLUMN escapements.escapement_id IS 'Primary key.';
COMMENT ON COLUMN escapements.in_timer IS 'Parent timer.';

-- ----------------------------------------------------------------------------
-- EscapementWheels: The toothed wheel of the escapement. Each pallet rock releases exactly one tooth.
-- ----------------------------------------------------------------------------
CREATE TABLE escapement_wheels (
  escapement_wheel_id                 TEXT                 PRIMARY KEY,         -- Primary key.
  in_escapement                       TEXT                ,                     -- Parent escapement.
  tooth_count                         INTEGER                                   -- Number of teeth around the wheel.
);
COMMENT ON TABLE escapement_wheels IS 'The toothed wheel of the escapement. Each pallet rock releases exactly one tooth.';
COMMENT ON COLUMN escapement_wheels.escapement_wheel_id IS 'Primary key.';
COMMENT ON COLUMN escapement_wheels.in_escapement IS 'Parent escapement.';
COMMENT ON COLUMN escapement_wheels.tooth_count IS 'Number of teeth around the wheel.';

-- ----------------------------------------------------------------------------
-- Pallets: Pivoting piece sitting across the escapement-wheel teeth. Two prongs (the README's 'two-pronged pallet'). Rocking is set by pallet mass plus the hairspring.
-- ----------------------------------------------------------------------------
CREATE TABLE pallets (
  pallet_id                           TEXT                 PRIMARY KEY,         -- Primary key.
  in_escapement                       TEXT                ,                     -- Parent escapement.
  prong_count                         INTEGER             ,                     -- Number of prongs. Always 2 on this design.
  mass_grams                          NUMERIC                                   -- Pallet mass. Co-determines rocking rate.
);
COMMENT ON TABLE pallets IS 'Pivoting piece sitting across the escapement-wheel teeth. Two prongs (the README''s ''two-pronged pallet''). Rocking is set by pallet mass plus the hairspring.';
COMMENT ON COLUMN pallets.pallet_id IS 'Primary key.';
COMMENT ON COLUMN pallets.in_escapement IS 'Parent escapement.';
COMMENT ON COLUMN pallets.prong_count IS 'Number of prongs. Always 2 on this design.';
COMMENT ON COLUMN pallets.mass_grams IS 'Pallet mass. Co-determines rocking rate.';

-- ----------------------------------------------------------------------------
-- Hairsprings: Tiny coiled spring attached to the pallet. Sets the pallet's rocking rate together with pallet mass.
-- ----------------------------------------------------------------------------
CREATE TABLE hairsprings (
  hairspring_id                       TEXT                 PRIMARY KEY,         -- Primary key.
  attached_to_pallet                  TEXT                ,                     -- Parent pallet.
  stiffness_nm_per_rad                NUMERIC                                   -- Torsional stiffness.
);
COMMENT ON TABLE hairsprings IS 'Tiny coiled spring attached to the pallet. Sets the pallet''s rocking rate together with pallet mass.';
COMMENT ON COLUMN hairsprings.hairspring_id IS 'Primary key.';
COMMENT ON COLUMN hairsprings.attached_to_pallet IS 'Parent pallet.';
COMMENT ON COLUMN hairsprings.stiffness_nm_per_rad IS 'Torsional stiffness.';

-- ----------------------------------------------------------------------------
-- Cams: Profile on the arbor of §2. Its notch aligns with the hammer catch at the zero position; that alignment is what trips §5.
-- ----------------------------------------------------------------------------
CREATE TABLE cams (
  cam_id                              TEXT                 PRIMARY KEY,         -- Primary key.
  on_arbor                            TEXT                ,                     -- Arbor this cam rides on.
  notch_angle_deg                     NUMERIC                                   -- Arbor angle at which the notch aligns with the catch.
);
COMMENT ON TABLE cams IS 'Profile on the arbor of §2. Its notch aligns with the hammer catch at the zero position; that alignment is what trips §5.';
COMMENT ON COLUMN cams.cam_id IS 'Primary key.';
COMMENT ON COLUMN cams.on_arbor IS 'Arbor this cam rides on.';
COMMENT ON COLUMN cams.notch_angle_deg IS 'Arbor angle at which the notch aligns with the catch.';

-- ----------------------------------------------------------------------------
-- BellHammers: §5 — spring-loaded arm with a steel striker, held back by the hammer catch. When the cam notch reaches the catch, the catch releases and the arm's own spring snaps the striker against the bell.
-- ----------------------------------------------------------------------------
CREATE TABLE bell_hammers (
  bell_hammer_id                      TEXT                 PRIMARY KEY,         -- Primary key.
  in_timer                            TEXT                ,                     -- Parent timer.
  arm_torque_nm                       NUMERIC                                   -- Spring torque stored in the hammer arm.
);
COMMENT ON TABLE bell_hammers IS '§5 — spring-loaded arm with a steel striker, held back by the hammer catch. When the cam notch reaches the catch, the catch releases and the arm''s own spring snaps the striker against the bell.';
COMMENT ON COLUMN bell_hammers.bell_hammer_id IS 'Primary key.';
COMMENT ON COLUMN bell_hammers.in_timer IS 'Parent timer.';
COMMENT ON COLUMN bell_hammers.arm_torque_nm IS 'Spring torque stored in the hammer arm.';

-- ----------------------------------------------------------------------------
-- HammerArms: The spring-loaded arm of the bell hammer. Carries the striker at its tip.
-- ----------------------------------------------------------------------------
CREATE TABLE hammer_arms (
  hammer_arm_id                       TEXT                 PRIMARY KEY,         -- Primary key.
  of_bell_hammer                      TEXT                ,                     -- Parent bell hammer.
  length_mm                           NUMERIC                                   -- Arm length.
);
COMMENT ON TABLE hammer_arms IS 'The spring-loaded arm of the bell hammer. Carries the striker at its tip.';
COMMENT ON COLUMN hammer_arms.hammer_arm_id IS 'Primary key.';
COMMENT ON COLUMN hammer_arms.of_bell_hammer IS 'Parent bell hammer.';
COMMENT ON COLUMN hammer_arms.length_mm IS 'Arm length.';

-- ----------------------------------------------------------------------------
-- Strikers: The small steel head at the tip of the hammer arm. Whatever actually contacts the bell.
-- ----------------------------------------------------------------------------
CREATE TABLE strikers (
  striker_id                          TEXT                 PRIMARY KEY,         -- Primary key.
  on_arm                              TEXT                ,                     -- Hammer arm this striker is mounted on.
  material                            TEXT                                      -- Striker material.
);
COMMENT ON TABLE strikers IS 'The small steel head at the tip of the hammer arm. Whatever actually contacts the bell.';
COMMENT ON COLUMN strikers.striker_id IS 'Primary key.';
COMMENT ON COLUMN strikers.on_arm IS 'Hammer arm this striker is mounted on.';
COMMENT ON COLUMN strikers.material IS 'Striker material.';

-- ----------------------------------------------------------------------------
-- HammerCatches: Catch that holds the hammer back until the cam notch aligns. Once released, the arm spring snaps the striker against the bell.
-- ----------------------------------------------------------------------------
CREATE TABLE hammer_catches (
  hammer_catch_id                     TEXT                 PRIMARY KEY,         -- Primary key.
  of_bell_hammer                      TEXT                ,                     -- Parent bell hammer.
  engaged_with_cam                    TEXT                                      -- Cam this catch rides against.
);
COMMENT ON TABLE hammer_catches IS 'Catch that holds the hammer back until the cam notch aligns. Once released, the arm spring snaps the striker against the bell.';
COMMENT ON COLUMN hammer_catches.hammer_catch_id IS 'Primary key.';
COMMENT ON COLUMN hammer_catches.of_bell_hammer IS 'Parent bell hammer.';
COMMENT ON COLUMN hammer_catches.engaged_with_cam IS 'Cam this catch rides against.';

-- ----------------------------------------------------------------------------
-- WindActions: Event: a user rotates the winding knob to a target angle at a point in time. The README's §1 input event.
-- ----------------------------------------------------------------------------
CREATE TABLE wind_actions (
  wind_action_id                      TEXT                 PRIMARY KEY,         -- Primary key.
  performed_by                        TEXT                ,                     -- Acting user.
  turned_knob                         TEXT                ,                     -- Knob that was turned.
  target_angle_deg                    NUMERIC             ,                     -- Angle wound to, in degrees.
  occurred_at                         TIMESTAMPTZ                               -- When the wind happened.
);
COMMENT ON TABLE wind_actions IS 'Event: a user rotates the winding knob to a target angle at a point in time. The README''s §1 input event.';
COMMENT ON COLUMN wind_actions.wind_action_id IS 'Primary key.';
COMMENT ON COLUMN wind_actions.performed_by IS 'Acting user.';
COMMENT ON COLUMN wind_actions.turned_knob IS 'Knob that was turned.';
COMMENT ON COLUMN wind_actions.target_angle_deg IS 'Angle wound to, in degrees.';
COMMENT ON COLUMN wind_actions.occurred_at IS 'When the wind happened.';

-- ----------------------------------------------------------------------------
-- TickEvents: Event: the escapement releases one tooth — one 'tick' from the README.
-- ----------------------------------------------------------------------------
CREATE TABLE tick_events (
  tick_event_id                       TEXT                 PRIMARY KEY,         -- Primary key.
  happened_on_timer                   TEXT                ,                     -- Parent timer.
  at_escapement                       TEXT                ,                     -- Escapement that ticked.
  occurred_at                         TIMESTAMPTZ                               -- Tick timestamp.
);
COMMENT ON TABLE tick_events IS 'Event: the escapement releases one tooth — one ''tick'' from the README.';
COMMENT ON COLUMN tick_events.tick_event_id IS 'Primary key.';
COMMENT ON COLUMN tick_events.happened_on_timer IS 'Parent timer.';
COMMENT ON COLUMN tick_events.at_escapement IS 'Escapement that ticked.';
COMMENT ON COLUMN tick_events.occurred_at IS 'Tick timestamp.';

-- ----------------------------------------------------------------------------
-- RingEvents: Event: the bell hammer strikes the bell — the README's 'ding'. Recorded once per fired §5.
-- ----------------------------------------------------------------------------
CREATE TABLE ring_events (
  ring_event_id                       TEXT                 PRIMARY KEY,         -- Primary key.
  happened_on_timer                   TEXT                ,                     -- Parent timer.
  struck                              TEXT                ,                     -- Bell that was struck.
  occurred_at                         TIMESTAMPTZ                               -- Ring timestamp.
);
COMMENT ON TABLE ring_events IS 'Event: the bell hammer strikes the bell — the README''s ''ding''. Recorded once per fired §5.';
COMMENT ON COLUMN ring_events.ring_event_id IS 'Primary key.';
COMMENT ON COLUMN ring_events.happened_on_timer IS 'Parent timer.';
COMMENT ON COLUMN ring_events.struck IS 'Bell that was struck.';
COMMENT ON COLUMN ring_events.occurred_at IS 'Ring timestamp.';

-- ----------------------------------------------------------------------------
-- Cooks: A dish being timed on a timer. Each cook started at the moment a user wound the timer; its status mirrors the timer's lifecycle.
-- ----------------------------------------------------------------------------
CREATE TABLE cooks (
  cook_id                             TEXT                 PRIMARY KEY,         -- Primary key.
  on_timer                            TEXT                ,                     -- Timer being used.
  prepared_by                         TEXT                ,                     -- User preparing the dish.
  dish_name                           TEXT                ,                     -- Name of the dish.
  started_at                          TIMESTAMPTZ         ,                     -- When the dish was started — i.e. when the timer was wound.
  follows_recipe                      TEXT                                      -- Recipe being followed.
);
COMMENT ON TABLE cooks IS 'A dish being timed on a timer. Each cook started at the moment a user wound the timer; its status mirrors the timer''s lifecycle.';
COMMENT ON COLUMN cooks.cook_id IS 'Primary key.';
COMMENT ON COLUMN cooks.on_timer IS 'Timer being used.';
COMMENT ON COLUMN cooks.prepared_by IS 'User preparing the dish.';
COMMENT ON COLUMN cooks.dish_name IS 'Name of the dish.';
COMMENT ON COLUMN cooks.started_at IS 'When the dish was started — i.e. when the timer was wound.';
COMMENT ON COLUMN cooks.follows_recipe IS 'Recipe being followed.';

-- ----------------------------------------------------------------------------
-- Recipes: Cooking recipes a cook can follow. Each names a dish and the minutes it should run.
-- ----------------------------------------------------------------------------
CREATE TABLE recipes (
  recipe_id                           TEXT                 PRIMARY KEY,         -- Primary key.
  dish_name                           TEXT                ,                     -- Name of the dish.
  recommended_minutes                 NUMERIC             ,                     -- Recommended cook time, in minutes.
  ideal_temperature_c                 NUMERIC                                   -- Recommended cooking temperature, in degrees Celsius.
);
COMMENT ON TABLE recipes IS 'Cooking recipes a cook can follow. Each names a dish and the minutes it should run.';
COMMENT ON COLUMN recipes.recipe_id IS 'Primary key.';
COMMENT ON COLUMN recipes.dish_name IS 'Name of the dish.';
COMMENT ON COLUMN recipes.recommended_minutes IS 'Recommended cook time, in minutes.';
COMMENT ON COLUMN recipes.ideal_temperature_c IS 'Recommended cooking temperature, in degrees Celsius.';

-- ----------------------------------------------------------------------------
-- Kitchens: A kitchen, top of the rollup tree. Aggregates everything below it.
-- ----------------------------------------------------------------------------
CREATE TABLE kitchens (
  kitchen_id                          TEXT                 PRIMARY KEY,         -- Primary key.
  display_name                        TEXT                                      -- Human name.
);
COMMENT ON TABLE kitchens IS 'A kitchen, top of the rollup tree. Aggregates everything below it.';
COMMENT ON COLUMN kitchens.kitchen_id IS 'Primary key.';
COMMENT ON COLUMN kitchens.display_name IS 'Human name.';

